30: /* utility routines to implement the various stopping criteria */
31: 
32: static double sc(double x, double smin, double smax)
33: {
34:     return smin + x * (smax - smin);
35: }
36: 
37: static double vector_norm(unsigned n, const double *vec, const double *w, const double *scale_min, const double *scale_max)
38: {
39:     unsigned i;
40:     double ret = 0;
41:     if (scale_min && scale_max) {
42:         if (w)
43:             for (i = 0; i < n; i++)
44:                 ret += w[i] * fabs(sc(vec[i], scale_min[i], scale_max[i]));
45:         else
46:             for (i = 0; i < n; i++)
47:                 ret += fabs(sc(vec[i], scale_min[i], scale_max[i]));
48:     } else {
49:         if (w)
50:             for (i = 0; i < n; i++)
51:                 ret += w[i] * fabs(vec[i]);
52:         else
53:             for (i = 0; i < n; i++)
54:                 ret += fabs(vec[i]);
55:     }
56:     return ret;
57: }
58: 
59: static double diff_norm(unsigned n, const double *x, const double *oldx, const double *w, const double *scale_min, const double *scale_max)
60: {
61:     unsigned i;
62:     double ret = 0;
63:     if (scale_min && scale_max) {
64:         if (w)
65:             for (i = 0; i < n; i++)
66:                 ret += w[i] * fabs(sc(x[i], scale_min[i], scale_max[i]) - sc(oldx[i], scale_min[i], scale_max[i]));
67:         else
68:             for (i = 0; i < n; i++)
69:                 ret += fabs(sc(x[i], scale_min[i], scale_max[i]) - sc(oldx[i], scale_min[i], scale_max[i]));
70:     } else {
71:         if (w)
72:             for (i = 0; i < n; i++)
73:                 ret += w[i] * fabs(x[i] - oldx[i]);
74:         else
75:             for (i = 0; i < n; i++)
76:                 ret += fabs(x[i] - oldx[i]);
77:     }
78:     return ret;
79: }
80: 
81: static int relstop(double vold, double vnew, double reltol, double abstol)
82: {
83:     if (nlopt_isinf(vold))
84:         return 0;
85:     return (fabs(vnew - vold) < abstol || fabs(vnew - vold) < reltol * (fabs(vnew) + fabs(vold)) * 0.5 || (reltol > 0 && vnew == vold));        /* catch vnew == vold == 0 */
86: }
87: 
88: int nlopt_stop_ftol(const nlopt_stopping * s, double f, double oldf)
89: {
90:     return (relstop(oldf, f, s->ftol_rel, s->ftol_abs));
91: }
92: 
93: int nlopt_stop_f(const nlopt_stopping * s, double f, double oldf)
94: {
95:     return (f <= s->minf_max || nlopt_stop_ftol(s, f, oldf));
96: }
97: 
98: int nlopt_stop_x(const nlopt_stopping * s, const double *x, const double *oldx)
99: {
100:     unsigned i;
101:     if (diff_norm(s->n, x, oldx, s->x_weights, NULL, NULL) < s->xtol_rel * vector_norm(s->n, x, s->x_weights, NULL, NULL))
102:         return 1;
103:     if (!s->xtol_abs) return 0;
104:     for (i = 0; i < s->n; ++i)
105:         if (fabs(x[i] - oldx[i]) >= s->xtol_abs[i])
106:             return 0;
107:     return 1;
108: }
109: 
110: int nlopt_stop_dx(const nlopt_stopping * s, const double *x, const double *dx)
111: {
112:     unsigned i;
113:     if (vector_norm(s->n, dx, s->x_weights, NULL, NULL) < s->xtol_rel * vector_norm(s->n, x, s->x_weights, NULL, NULL))
114:         return 1;
115:     if (!s->xtol_abs) return 0;
116:     for (i = 0; i < s->n; ++i)
117:         if (fabs(dx[i]) >= s->xtol_abs[i])
118:             return 0;
119:     return 1;
120: }
121: 
122: /* some of the algorithms rescale x to a unit hypercube, so we need to
123:    scale back before we can compare to the tolerances */
124: int nlopt_stop_xs(const nlopt_stopping * s, const double *xs, const double *oldxs, const double *scale_min, const double *scale_max)
125: {
126:     unsigned i;
127:     if (diff_norm(s->n, xs, oldxs, s->x_weights, scale_min, scale_max) < s->xtol_rel * vector_norm(s->n, xs, s->x_weights, scale_min, scale_max))
128:         return 1;
129:     if (!s->xtol_abs) return 0;
130:     for (i = 0; i < s->n; ++i)
131:         if (fabs(sc(xs[i], scale_min[i], scale_max[i]) - sc(oldxs[i], scale_min[i], scale_max[i])) >= s->xtol_abs[i])
132:             return 0;
133:     return 1;
134: }
