141: int nlopt_stop_time_(double start, double maxtime)
142: {
143:     return (maxtime > 0 && nlopt_seconds() - start >= maxtime);
144: }
145: 
146: int nlopt_stop_time(const nlopt_stopping * s)
147: {
148:     return nlopt_stop_time_(s->start, s->maxtime);
149: }
150: 
151: int nlopt_stop_evalstime(const nlopt_stopping * stop)
152: {
153:     return nlopt_stop_evals(stop) || nlopt_stop_time(stop);
154: }
