186: char *nlopt_vsprintf(char *p, const char *format, va_list ap)
187: {
188:     size_t len = strlen(format) + 128;
189:     int ret;
190: 
191:     p = (char *) realloc(p, len);
192:     if (!p)
193:         abort();
194: 
195:     /* TODO: check HAVE_VSNPRINTF, and fallback to vsprintf otherwise */
196:     while ((ret = vsnprintf(p, len, format, ap)) < 0 || (size_t) ret >= len) {
197:         /* C99 vsnprintf returns the required number of bytes (excluding \0)
198:            if the buffer is too small; older versions (e.g. MS) return -1 */
199:         len = ret >= 0 ? (size_t) (ret + 1) : (len * 3) >> 1;
200:         p = (char *) realloc(p, len);
201:         if (!p)
202:             abort();
203:     }
204:     return p;
205: }
