26	Trial HookeJeevesOptimizer::Optimize(std::shared_ptr<IGOProblem<double>> problem,
27	                                    const Trial& startPoint, std::vector<unsigned>& trialsCounters)
28	{
29	  mProblem = problem;
30	  mStartPoint = startPoint;
31	  mTrialsCounters = std::vector<unsigned>(mProblem->GetConstraintsNumber() + 1, 0);
32	
33	  int k = 0, i=0;
34	  bool needRestart = true;
35	  /* currentFvalue will be initialized below, init here to avoid maybe-uninitialized warning */
36	  double currentFValue = 0.0, nextFValue;
37	
38	  while (i < MAX_LOCAL_ITERATIONS_NUMBER)	{
39	    i++;
40	    if (needRestart)	{
41	      k = 0;
42	      mCurrentPoint = mStartPoint;
43	      mCurrentResearchDirection = mStartPoint;
44	      currentFValue = ComputeObjective(mCurrentPoint.y);
45	      needRestart = false;
46	    }
47	
48	    std::swap(mPreviousResearchDirection, mCurrentResearchDirection);
49	    mCurrentResearchDirection = mCurrentPoint;
50	    nextFValue = MakeResearch(mCurrentResearchDirection.y);
51	
52	    if (currentFValue > nextFValue)	{
53	      DoStep();
54	      k++;
55	      currentFValue = nextFValue;
56	    }
57	    else if (mStep > mEps)	{
58	      if (k != 0)
59	        std::swap(mStartPoint, mPreviousResearchDirection);
60	      else
61	        mStep /= mStepMultiplier;
62	      needRestart = true;
63	    }
64	    else
65	      break;
66	  }
67	
68	  mPreviousResearchDirection.idx = 0;
69	  while (mPreviousResearchDirection.idx < mProblem->GetConstraintsNumber())
70	  {
