72	    mPreviousResearchDirection.g[mPreviousResearchDirection.idx] =
73	      mProblem->Calculate(mPreviousResearchDirection.y, mPreviousResearchDirection.idx);
74	    if (mPreviousResearchDirection.g[mPreviousResearchDirection.idx] > 0)
75	      break;
76	    mPreviousResearchDirection.idx++;
77	  }
78	
