93	{
94	  for (int i = 0; i < mProblem->GetDimension(); i++)
95	    mCurrentPoint.y[i] = (1 + mStepMultiplier)*mCurrentResearchDirection.y[i] -
96	      mStepMultiplier*mPreviousResearchDirection.y[i];
