99	double HookeJeevesOptimizer::ComputeObjective(const double* x) const
100	{
101	  for (int i = 0; i <= mProblem->GetConstraintsNumber(); i++)
102	  {
103	    double value = mProblem->Calculate(x, i);
104	    mTrialsCounters[i]++;
105	    if (i < mProblem->GetConstraintsNumber() && value > 0)
106	      return std::numeric_limits<double>::max();
107	    else if (i == mProblem->GetConstraintsNumber())
108	      return value;
109	  }
110	  return std::numeric_limits<double>::max();
111	}
112	
113	double HookeJeevesOptimizer::MakeResearch(double* startPoint)
114	{
115	  double bestValue = ComputeObjective(startPoint);
116	
117	  for (int i = 0; i < mProblem->GetDimension(); i++)
118	  {
119	    startPoint[i] += mStep;
120	    double rightFvalue = ComputeObjective(startPoint);
121	
122	    if (rightFvalue > bestValue)
123	    {
124	      startPoint[i] -= 2 * mStep;
125	      double leftFValue = ComputeObjective(startPoint);
126	      if (leftFValue > bestValue)
127	        startPoint[i] += mStep;
128	      else
129	        bestValue = leftFValue;
130	    }
131	    else
132	      bestValue = rightFvalue;
133	  }
134	
135	  return bestValue;
136	}
