557	/* in the conventional DIRECT-type algorithm, we first rescale our
558	   coordinates to a unit hypercube ... we do this simply by
559	   wrapping cdirect() around cdirect_unscaled(). */
560	
561	double cdirect_uf(unsigned n, const double *xu, double *grad, void *d_)
562	{
563	     cdirect_uf_data *d = (cdirect_uf_data *) d_;
564	     double f;
565	     unsigned i;
566	     for (i = 0; i < n; ++i)
567		  d->x[i] = d->lb[i] + xu[i] * (d->ub[i] - d->lb[i]);
568	     f = d->f(n, d->x, grad, d->f_data);
569	     if (grad)
570		  for (i = 0; i < n; ++i)
571		       grad[i] *= d->ub[i] - d->lb[i];
572	     return f;
573	}
