576	                     const double *lb, const double *ub,
577	                     double *x,
578	                     double *minf,
579	                     nlopt_stopping *stop,
580	                     double magic_eps, int which_alg)
581	{
582	     cdirect_uf_data d;
583	     nlopt_result ret;
584	     const double *xtol_abs_save = NULL;
585	     int i;
