588	     d.x = (double *) calloc(n * (stop->xtol_abs ? 4 : 3), sizeof(double));
589	     if (!d.x) return NLOPT_OUT_OF_MEMORY;
590	     
591	     for (i = 0; i < n; ++i) {
592		  x[i] = (x[i] - lb[i]) / (ub[i] - lb[i]);
593		  d.x[n+i] = 0;
594		  d.x[2*n+i] = 1;
595	     }
596	     if (stop->xtol_abs) {
597	       for (i = 0; i < n; ++i)
598	         d.x[3*n+i] = stop->xtol_abs[i] / (ub[i] - lb[i]);
599	       xtol_abs_save = stop->xtol_abs;
600	       stop->xtol_abs = d.x + 3*n;
601	     }
602	     ret = cdirect_unscaled(n, cdirect_uf, &d, d.x+n, d.x+2*n, x, minf, stop,
603				    magic_eps, which_alg);
